 with time zone","master":false,"location":null,"inventory_location":false,"parent":null,"tenant_column":true},{"key":"user_roles","label":"User roles","group":"Controls & evidence","entity":"user_role","sources":[],"date":"created_at","date_type":"timestamp with time zone","master":true,"location":null,"inventory_location":false,"parent":null,"tenant_column":true},{"key":"workforce_audit_v630","label":"Workforce audit","group":"Staff & wages","entity":"workforce_audit","sources":[],"date":"created_at","date_type":"timestamp with time zone","master":false,"location":null,"inventory_location":false,"parent":["staff_id","staff_members_v630"],"tenant_column":true},{"key":"workshop_job_cards","label":"Workshop job cards","group":"Services & workshop","entity":"workshop_job_card","sources":[],"date":"created_at","date_type":"timestamp with time zone","master":false,"location":"location_id","inventory_location":false,"parent":null,"tenant_column":true},{"key":"workshop_vehicles","label":"Workshop vehicles","group":"Services & workshop","entity":"workshop_vehicle","sources":[],"date":"created_at","date_type":"timestamp with time zone","master":true,"location":"location_id","inventory_location":false,"parent":null,"tenant_column":true}]'::jsonb $catalog$;
revoke all on function private.audit_catalog_v704() from public,anon,authenticated;

create or replace function private.audit_clean_v704(v jsonb, sensitive boolean) returns jsonb
language plpgsql immutable set search_path='' as $$
declare outv jsonb; k text; x jsonb;
begin
 if jsonb_typeof(v)='object' then
  outv:='{}';
  for k,x in select * from jsonb_each(v) loop
   if k ~* '(secret|password|token|credential|activation_hash|provider_config|stack_trace)' then continue;end if;
   if not sensitive and k in('before_data','after_data','before_state','after_state','bank_account','bank_ifsc','payee_snapshot','address','emergency_contact') then continue;end if;
   outv:=outv||jsonb_build_object(k,private.audit_clean_v704(x,sensitive));
  end loop;return outv;
 elsif jsonb_typeof(v)='array' then
  select coalesce(jsonb_agg(private.audit_clean_v704(value,sensitive)),'[]') into outv from jsonb_array_elements(v);return outv;
 end if;return v;
end $$;
revoke all on function private.audit_clean_v704(jsonb,boolean) from public,anon,authenticated;

create or replace function private.audit_record_locations_v704(t uuid, dataset text, r jsonb, depth integer default 0) returns uuid[]
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb; lid uuid; par jsonb; locations uuid[]; eid uuid; typ text; child text;
begin
 if depth>5 then return array[null::uuid];end if;
 select value into cfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=dataset;
 if cfg is null then return array[null::uuid];end if;
 lid:=nullif(r->>(cfg->>'location'),'')::uuid;
 if lid is not null then
  if coalesce((cfg->>'inventory_location')::boolean,false) then
   select array_agg(id order by id) into locations from public.business_locations where tenant_id=t and inventory_location_id=lid;
   return coalesce(locations,array[null::uuid]);
  end if;
  if dataset in('stock_transfers','stock_transfer_allocations_v485','transport_logistics_trips') then
   return array[lid,nullif(r->>'to_location_id','')::uuid];
  end if;
  return array[lid];
 end if;
 if cfg->'parent'<>'null'::jsonb and nullif(r->>(cfg#>>'{parent,0}'),'') is not null then
  execute format('select to_jsonb(x) from public.%I x where x.tenant_id=$1 and x.id=$2',cfg#>>'{parent,1}') into par using t,(r->>(cfg#>>'{parent,0}'))::uuid;
  if par is not null then return private.audit_record_locations_v704(t,cfg#>>'{parent,1}',par,depth+1);end if;
 end if;
 eid:=case when r->>'id' ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F-]{27}$' then (r->>'id')::uuid else null end;typ:=cfg->>'entity';
 if r ? 'entity_id' then eid:=nullif(r->>'entity_id','')::uuid;typ:=r->>'entity_type';end if;
 if dataset in('gst_document_snapshots_v520','gst_legacy_document_markers_v520') then eid:=(r->>'source_id')::uuid;typ:=r->>'source_type';end if;
 if eid is not null then
  select array_agg(distinct location_id) into locations from public.document_origins where tenant_id=t and entity_id=eid and entity_type=typ;
  if locations is not null then return locations;end if;
  select value->>'key' into child from jsonb_array_elements(private.audit_catalog_v704()) where value->>'entity'=typ and value->>'key'<>dataset limit 1;
  if child is not null then
   execute format('select to_jsonb(x) from public.%I x where x.tenant_id=$1 and x.id=$2',child) into par using t,eid;
   if par is not null then return private.audit_record_locations_v704(t,child,par,depth+1);end if;
  end if;
  select array_agg(distinct location_id) into locations from public.journal_entries where tenant_id=t and source_id=eid and source_type=typ;
  if locations is not null then return locations;end if;
 end if;
 return array[null::uuid];
end $$;
revoke all on function private.audit_record_locations_v704(uuid,text,jsonb,integer) from public,anon,authenticated;

create or replace function private.audit_record_allowed_v704(t uuid,dataset text,r jsonb,loc uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from unnest(private.audit_record_locations_v704(t,dataset,r)) l where private.reports_scope_v631(t,l,loc,'view'))
$$;
revoke all on function private.audit_record_allowed_v704(uuid,text,jsonb,uuid) from public,anon,authenticated;

create or replace function private.audit_evidence_v704(t uuid,dataset text,f date,z date,loc uuid,q text,off integer,lim integer) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare cfg jsonb;raw jsonb;matched jsonb;page jsonb;tz text;lo timestamptz;hi timestamptz;date_clause text:='';tenant_clause text;sensitive boolean;
begin
 perform private.audit_access_v703(t,loc);
 if f is null or z is null or f>z or off is null or off<0 or lim is null or lim<1 or lim>200 or length(coalesce(q,''))>200 then raise exception 'Invalid evidence query' using errcode='22023';end if;
 select value into cfg from jsonb_array_elements(private.audit_catalog_v704()) where value->>'key'=dataset;
 if cfg is null then raise exception 'Unknown evidence dataset' using errcode='22023';end if;
 sensitive:=private.has_permission(t,'audit_history.view_sensitive');
 tz:=coalesce((select timezone from public.tenant_settings where tenant_id=t),'UTC');lo:=f::timestamp at time zone tz;hi:=(z+1)::timestamp at time zone tz;
 if not (cfg->>'master')::boolean and cfg->>'date' is not null then
  date_clause:=case when cfg->>'date_type'='date' then format(' and x.%I >= $7 and x.%I <= $8',cfg->>'date',cfg->>'date') else format(' and x.%I >= $3 and x.%I < $4',cfg->>'date',cfg->>'date') end;
 end if;
 tenant_clause:=case when (cfg->>'tenant_column')::boolean then 'x.tenant_id=$1' else format('exists(select 1 from public.%I p where p.tenant_id=$1 and p.id=x.%I)',cfg#>>'{parent,1}',cfg#>>'{parent,0}') end;
 execute format('select coalesce(jsonb_agg(private.audit_clean_v704(to_jsonb(x),$5)),''[]''::jsonb) from public.%I x where %s and private.audit_record_allowed_v704($1,$6,to_jsonb(x),$2)%s',dataset,tenant_clause,date_clause)
 into raw using t,loc,lo,hi,sensitive,dataset,f,z;
 with normalized as (
  select x, coalesce(x->>'id',md5(x::text)) rid,
   coalesce(x->>'sale_number',x->>'purchase_number',x->>'invoice_number',x->>'return_number',x->>'entry_number',x->>'receipt_number',x->>'payment_number',x->>'settlement_number',x->>'load_number',x->>'order_number',x->>'loan_number',x->>'run_number',x->>'trip_number',x->>'voucher_number',x->>'count_number',x->>'transfer_number',x->>'staff_code',x->>'reference_number',x->>'reference',x->>'tracking_code',x->>'name',x->>'account_name',x->>'batch_number',x->>'serial_number',x->>'file_name',x->>'code',x->>'entity_reference',cfg->>'label') ref
  from jsonb_array_elements(raw) x
 ), enriched as (
  select x,rid,ref,
   jsonb_build_object('id',rid,'dataset',dataset,'reference',ref,'date',x->>(cfg->>'date'),'status',coalesce(x->>'status',x->>'verification_status',x->>'event_type',x->>'action',case when x ? 'active' then case when (x->>'active')::boolean then 'Active' else 'Archived' end else 'Recorded' end),
    'party',coalesce(x->>'customer_name',x->>'supplier_name',x->>'payee',x->>'driver_name_snapshot',x->>'driver_name',x->>'name',x->>'description',x->>'title',
     (select name from public.staff_members_v630 where tenant_id=t and id=nullif(x->>'staff_id','')::uuid),
     (select name from public.customers where tenant_id=t and id=nullif(x->>'customer_id','')::uuid),
     (select name from public.suppliers where tenant_id=t and id=nullif(x->>'supplier_id','')::uuid)),
    'amount',coalesce(x->'grand_total',x->'total_amount',x->'amount',x->'line_total',x->'gross_amount',x->'principal_amount'),
    'quantity',coalesce(x->'quantity',x->'quantity_delta',x->'units',x->'ordered_quantity'),
    'location',coalesce((select string_agg(b.location_code,' / ' order by b.location_code) from public.business_locations b where b.tenant_id=t and b.id=any(private.audit_record_locations_v704(t,dataset,x))),'Unassigned / business-wide'),
    'actor',(select display_name from public.profiles where id=coalesce(nullif(x->>'created_by',''),nullif(x->>'changed_by',''),nullif(x->>'actor_user_id',''),nullif(x->>'uploaded_by',''),nullif(x->>'updated_by',''))::uuid),
    'journal_count',(select count(*) from public.journal_entries j where j.tenant_id=t and private.reports_scope_v631(t,j.location_id,loc,'view') and (j.id::text=x->>'journal_id' or (j.source_id::text=x->>'id' and (cfg->'sources') ? j.source_type))),
    'record',x) row
  from normalized
 ) select coalesce(jsonb_agg(row order by row->>'date' desc nulls last,ref,rid),'[]') into matched from enriched where private.accounting_search_v702(row-'record',q) or private.accounting_search_v702(x,q);
 select coalesce(jsonb_agg(value order by ordinality),'[]') into page from jsonb_array_elements(matched) with ordinality where ordinality>off and ordinality<=off+lim;
 return jsonb_build_object('rows',page,'total_rows',jsonb_array_length(matched),'snapshot_token',md5(matched::text),'dataset',cfg->>'label','period_basis',case when (cfg->>'master')::boolean then 'Current saved records; period does not filter master data or current balances.' else 'Selected period, using '||(cfg->>'date') end,'sensitive_values_visible',sensitive,'generated_at',statement_timestamp());
end $$;
revoke all on function private.audit_evidence_v704(uuid,text,date,date,uuid,text,integer,integer) from public,anon;
grant execute on function private.audit_evidence_v704(uuid,text,date,date,uuid,text,integer,integer) to authenticated;
create or replace function public.audit_evidence_v704(p_tenant_id uuid,p_dataset text,p_from date,p_to date,p_location_id uuid default null,p_query text default '',p_offset integer default 0,p_limit integer default 50) returns jsonb
language sql stable security invoker set search_path='' as $$ select private.audit_evidence_v704(p_tenant_id,p_dataset,p_from,p_to,p_location_id,p_query,p_offset,p_limit) $$;
revoke all on function public.audit_evidence_v704(uuid,text,date,date,uuid,text,integer,integer) from public,anon;
