create or replace function private.audit_catalog_visible_v704(t uuid,loc uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare r jsonb;
begin
 perform private.audit_access_v703(t,loc);
 select jsonb_agg(jsonb_build_object('key',value->>'key','label',value->>'label','group',value->>'group','master',value->'master') order by value->>'group',value->>'label') into r from jsonb_array_elements(private.audit_catalog_v704());return r;
end $$;
